import Foundation

/// T-Bank serves `invest-public-api.tinkoff.ru` with a certificate issued by the
/// Russian Trusted Root CA (Ministry of Digital Development), which iOS does not
/// ship in its system trust store. This delegate re-evaluates the server trust
/// with that root as an additional anchor — for that host only; every other host
/// keeps default system validation.
///
/// The root certificate (public, DER, valid to 2032) is embedded directly so the
/// fix never depends on a bundle resource being copied.
final class RussianTrustDelegate: NSObject, URLSessionDelegate {
    private static let pinnedHosts: Set<String> = ["invest-public-api.tinkoff.ru"]

    /// Russian Trusted Root CA, SHA-256 D2:6D:2D:02:31:B7:C3:9F:92:CC:73:85:12:BA:54:10:35:19:E4:40:5D:68:B5:BD:70:3E:97:88:CA:8E:CF:31
    private static let rootCertBase64 = """
    
    """

    private static let anchor: SecCertificate? = {
        guard let data = Data(base64Encoded: rootCertBase64.replacingOccurrences(of: "\n", with: "")) else {
            assertionFailure("Russian Trusted Root CA: base64 decode failed")
            return nil
        }
        guard let cert = SecCertificateCreateWithData(nil, data as CFData) else {
            assertionFailure("Russian Trusted Root CA: not a valid DER certificate")
            return nil
        }
        return cert
    }()

    func urlSession(_ session: URLSession,
                    didReceive challenge: URLAuthenticationChallenge,
                    completionHandler: @escaping (URLSession.AuthChallengeDisposition, URLCredential?) -> Void) {
        let space = challenge.protectionSpace
        guard space.authenticationMethod == NSURLAuthenticationMethodServerTrust,
              Self.pinnedHosts.contains(space.host),
              let trust = space.serverTrust,
              let anchor = Self.anchor else {
            completionHandler(.performDefaultHandling, nil)
            return
        }

        SecTrustSetAnchorCertificates(trust, [anchor] as CFArray)
        // Keep system anchors too, so a future switch back to a public CA keeps working.
        SecTrustSetAnchorCertificatesOnly(trust, false)

        var error: CFError?
        if SecTrustEvaluateWithError(trust, &error) {
            completionHandler(.useCredential, URLCredential(trust: trust))
        } else {
            NSLog("RussianTrustDelegate: trust evaluation failed for %@: %@",
                  space.host, String(describing: error))
            completionHandler(.cancelAuthenticationChallenge, nil)
        }
    }
}
